package org.example.server.persistence.repository;
import jakarta.persistence.LockModeType;import org.example.server.persistence.entity.SalesHeaderEntity;
import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;
import org.springframework.data.domain.Pageable;import java.util.*;
public interface SalesHeaderRepository extends JpaRepository<SalesHeaderEntity,Integer>{Optional<SalesHeaderEntity> findByInvoiceNo(String invoiceNo);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select sale from SalesHeaderEntity sale where sale.invoiceNo=:invoiceNo") Optional<SalesHeaderEntity> findByInvoiceNoForUpdate(@Param("invoiceNo") String invoiceNo);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select sale from SalesHeaderEntity sale where sale.id=:id") Optional<SalesHeaderEntity> findByIdForUpdate(@Param("id") Integer id); boolean existsByInvoiceNo(String invoiceNo); boolean existsByOrderNo(String orderNo); List<SalesHeaderEntity> findAllByOrderByInvoiceDateDescIdDesc(); @Query("select sale from SalesHeaderEntity sale where (coalesce(sale.totalAmount,0)-coalesce(sale.paidAmount,0)) > 0.009 and upper(coalesce(sale.documentStatus,'')) not in ('CANCELLED','DELETED','REJECTED','PENDING APPROVAL') order by abs((coalesce(sale.totalAmount,0)-coalesce(sale.paidAmount,0)) - :amount) asc, sale.invoiceDate desc, sale.id desc")  List<SalesHeaderEntity> findOpenForBankMatching(@Param("amount") double amount, Pageable pageable);}
